import React from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const EventsSlider = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    arrows: true,
    autoplay: true,
    autoplaySpeed: 3000,
    pauseOnHover: true,
  };

  const slides = [
    {
      id: 1,
      title: "TechCareer Staj Programı",
      description: "Kariyerine ilk adımı atmaya hazır mısın?",
      image: "https://via.placeholder.com/1024x394?text=Slide+1",
    },
    {
      id: 2,
      title: "Yeni Başlayanlar İçin Eğitimler",
      description: "Teknoloji dünyasına hızlı bir giriş yap.",
      image: "https://via.placeholder.com/1024x394?text=Slide+2",
    },
    {
      id: 3,
      title: "Mentorluk Programları",
      description: "Alanında uzman kişilerle çalış.",
      image: "https://via.placeholder.com/1024x394?text=Slide+3",
    },
  ];

  return (
    <div
      style={{
        position: "relative",
        width: "100%",
        maxWidth: "1024px",
        margin: "0 auto",
        border: "10px solid #00C26D",
        borderRadius: "10px",
        overflow: "hidden",
      }}
    >
      {/* Kesik Çizgiler */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          left: "10px",
          width: "150px",
          height: "5px",
          background: "repeating-linear-gradient(90deg, #00C26D, #00C26D 10px, transparent 10px, transparent 20px)",
        }}
      ></div>
      <div
        style={{
          position: "absolute",
          bottom: "10px",
          right: "10px",
          width: "150px",
          height: "5px",
          background: "repeating-linear-gradient(90deg, #00C26D, #00C26D 10px, transparent 10px, transparent 20px)",
        }}
      ></div>

      {/* Noktalar */}
      <div
        style={{
          position: "absolute",
          top: "10px",
          right: "10px",
          display: "flex",
          gap: "10px",
        }}
      >
        <div
          style={{
            width: "15px",
            height: "15px",
            backgroundColor: "#00C26D",
            borderRadius: "50%",
          }}
        ></div>
        <div
          style={{
            width: "15px",
            height: "15px",
            backgroundColor: "#00C26D",
            borderRadius: "50%",
          }}
        ></div>
      </div>

      <Slider {...settings}>
        {slides.map((slide) => (
          <div key={slide.id}>
            <div
              style={{
                height: "394px",
                backgroundImage: `url(${slide.image})`,
                backgroundSize: "cover",
                backgroundPosition: "center",
                position: "relative",
                color: "#fff",
                display: "flex",
                flexDirection: "column",
                justifyContent: "center",
                alignItems: "center",
                textAlign: "center",
                padding: "20px",
              }}
            >
              <h2 style={{ fontSize: "28px", marginBottom: "10px" }}>
                {slide.title}
              </h2>
              <p style={{ fontSize: "18px", maxWidth: "800px" }}>
                {slide.description}
              </p>
            </div>
          </div>
        ))}
      </Slider>
    </div>
  );
};

export default EventsSlider;
